mapper.update:
UPDATE routing.routing_case
   SET version = version + 1, updated_at = #{updatedAt}, updated_by = #{updatedBy},
       confirmed_route_version_no = #{confirmedRouteVersionNo}
 WHERE id = #{id} AND version = #{expectedVersion}

mapper.select:
SELECT COUNT(*) FROM routing.routing_case
 WHERE transport_request_id = #{transportRequestId}
   AND transport_request_version_no = #{transportRequestVersionNo}
